const deleteWorkspaceCockpitData = `-- name: DeleteWorkspaceCockpitData :exec
WITH del_changes AS (
    DELETE FROM cockpit_pending_change WHERE workspace_id = $1::uuid
), del_snapshots AS (
    DELETE FROM cockpit_snapshot WHERE workspace_id = $1::uuid
), del_links AS (
    DELETE FROM cockpit_node_issue WHERE workspace_id = $1::uuid
), del_payments AS (
    DELETE FROM cockpit_payment WHERE workspace_id = $1::uuid
), del_milestones AS (
    DELETE FROM cockpit_milestone WHERE workspace_id = $1::uuid
), del_meetings AS (
    DELETE FROM cockpit_meeting WHERE workspace_id = $1::uuid
), del_nodes AS (
    DELETE FROM cockpit_node WHERE workspace_id = $1::uuid
)
DELETE FROM cockpit WHERE workspace_id = $1::uuid
`

// Workspace teardown. One statement with data-modifying CTEs so the whole board
// goes in a single round trip; there are no foreign keys to cascade it
// (repository rule), and every cockpit table carries workspace_id for exactly
// this sweep.
func (q *Queries) DeleteWorkspaceCockpitData(ctx context.Context, workspaceID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, deleteWorkspaceCockpitData, workspaceID)
	return err
}

